import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.Safelist;
import java.util.*;

public class Rand {
    static Random rnd = new Random(42);
    static String[] tags = {"p","b","i","div","span","pre","code","textarea","table","tbody","tr","td","a","img","br","h1","ul","li","script","style","font","center","custom","x"};
    static String[] texts = {"a"," b ","a &amp; b","a < b","a > b","\"q\"","\\back","&lt;img src=x onerror=1&gt;","&#60;b&#62;","&nbsp;","\n","\t","  ","\n\t ","a&b","a&amp;amp;b","null\0here","<</>>","&","&amp","&#;","&#x;","日本語","𝄞",""};
    static String[] attrs = {"class='x'", "title=\"a &amp; b\"", "onclick='alert(1)'", "href='javascript:alert(1)'", "href='http://x.com'", "style='x:expression(1)'", "id=1", "src='x'", "=''", "malformed=\"x' y"};

    static String gen(int depth) {
        StringBuilder sb = new StringBuilder();
        int n = rnd.nextInt(4);
        for (int i = 0; i < n; i++) {
            int kind = rnd.nextInt(3);
            if (kind == 0) sb.append(texts[rnd.nextInt(texts.length)]);
            else if (kind == 1 && depth < 5) {
                String tag = tags[rnd.nextInt(tags.length)];
                sb.append("<").append(tag);
                if (rnd.nextBoolean()) sb.append(" ").append(attrs[rnd.nextInt(attrs.length)]);
                if (tag.equals("img") || tag.equals("br")) sb.append(">");
                else {
                    sb.append(">");
                    if (rnd.nextInt(3) != 0) sb.append(gen(depth+1));
                    if (rnd.nextInt(5) != 0) sb.append("</").append(tag).append(">");
                }
            } else {
                // raw junk
                sb.append(rnd.nextInt(2)==0 ? "<!-- c<b> -->" : "<![CDATA[<b>]]>");
            }
        }
        return sb.toString();
    }

    static boolean dangerous(Element e) {
        String n = e.normalName();
        if (n.equals("script") || n.equals("style")) return true;
        for (Attribute at : e.attributes())
            if (at.getKey().toLowerCase(Locale.ROOT).startsWith("on")) return true;
        for (Node c : e.childNodesCopy()) if (c instanceof Element && dangerous((Element)c)) return true;
        return false;
    }

    public static void main(String[] a) {
        Safelist sl = Safelist.none().addTags("p","b","i","div","span","pre","code","textarea","table","tbody","tr","td","a","img","br","h1","ul","li");
        Safelist other = Safelist.basic();
        int fails = 0;
        for (int it = 0; it < 20000; it++) {
            String html = gen(0);
            String c1, c2, c3;
            try {
                c1 = Jsoup.clean(html, sl);
                // interleave another safelist to detect state bleed
                Jsoup.clean(gen(0), other);
                c2 = Jsoup.clean(c1, sl);
                c3 = Jsoup.clean(c2, sl);
            } catch (Exception e) {
                System.out.println("EX: " + html.replace("\n","\\n") + " -> " + e);
                if (++fails > 20) break; else continue;
            }
            if (!c1.equals(c2) || !c2.equals(c3)) {
                System.out.println("NONIDEM:\n in: " + html.replace("\n","\\n") + "\n c1: " + c1.replace("\n","\\n") + "\n c2: " + c2.replace("\n","\\n") + "\n c3: " + c3.replace("\n","\\n"));
                if (++fails > 20) break;
            }
            Document d = Jsoup.parseBodyFragment(c1);
            for (Element e : d.getAllElements()) {
                for (Attribute at : e.attributes())
                    if (at.getKey().toLowerCase(Locale.ROOT).startsWith("on")) { System.out.println("LEAK: " + html); fails++; break; }
            }
            if (d.select("script,style,font,center").size() != 0) { System.out.println("LEAK tag: " + c1 + " from " + html); if (++fails>20) break; }
        }
        System.out.println(fails==0 ? "ALL OK 20000" : fails+" failures");
    }
}
