if (!isBlockEl(node.parentNode)) {
    // Inline elements keep their whitespace significant, unlike block parents. But whitespace sitting
    // where the printer is going to emit its own line break is not significant: that gap is
    // regenerated as indentation, and leaving it in the output makes it re-parse as literal text (so a
    // clean -> serialize -> reparse -> clean round trip gains spaces). Trim an edge only when (a) it
    // directly faces a block sibling, whose own head/tail emits the line break, or (b) it is the run at
    // the parent's opening/closing edge and that parent's content is laid out in blocks (so the parent's
    // own head/tail emits the break). Edges facing inline content are kept.
    Element parent = (Element) node.parentNode();
    Node prevNonBlank = previousNonblank(node);
    Node nextNonBlank = nextNonBlank(next);

    if (isBlockEl(prevNonBlank)
        || prev == null && isBlockEl(nextNonBlank)
        || prev == null && isBlockLayout(parent))
        options |= Entities.TrimLeading;

    if (isBlockEl(nextNonBlank)
        || next == null && shouldIndent(nextNonBlank(parent.firstChild()), false))
        options |= Entities.TrimTrailing;
    return options;
}

