/**
 The HTML parser discards a single line feed immediately following a {@code <pre>} or {@code <listing>} start tag
 (matching the HTML spec). Serialization mirrors that: when the element's first text child itself starts with a
 line feed, an extra line feed is emitted after the start tag, so that the intended line feed survives a
 serialize -> reparse round trip. Without it, clean output starting {@code <pre>\n...} would re-parse with one
 fewer newline and a second clean would change the markup.
 */
private boolean needsLeadingNewlineCompensation(Document.OutputSettings out) {
    if (out.syntax() == xml || !tag.namespace().equals(NamespaceHtml)) return false;
    if (!nameIs("pre") && !nameIs("listing")) return false;
    Node first = childNodes.get(0);
    return first instanceof TextNode && ((TextNode) first).getWholeText().startsWith("\n");
}

