import org.jsoup.safety.Safelist;
import java.util.List;

public class Dbg {
    static void walk(Node n, String ind) {
        if (n instanceof Element) {
            System.out.println(ind + "<" + n.nodeName() + ">");
            for (Node c : n.childNodes()) walk(c, ind + "  ");
        } else {
            String v = n.toString().replace("\n","\\n");
            System.out.println(ind + "[" + n.getClass().getSimpleName() + "] " + (v.length()>30?v.substring(0,30):v));
