@Override
void addText(TextNode node, int textOptions, int depth) {
    if (!preserveWhitespace) {
        textOptions |= Entities.Normalise;
        textOptions = textTrim(node, textOptions);

        if (!node.isBlank() && isBlockEl(node.parentNode) && shouldIndent(node))
            indent(depth);
    }

    super.addText(node, textOptions, depth);
}

int textTrim(TextNode node, int options) {
    Node parent = node.parentNode();
    if (parent == null || !isBlockEl(parent)) {
        trimInlineWhitespace(node, parent, options == 0 ? 0 : options);
        // inline whitespace is significant and not trimmed by default
        if (parent == null || !node.isBlank()) return options;
        return trimInlineWhitespace(node, (Element) parent, options);
    }
    Node prev = node.previousSibling();
    Node next = node.nextSibling();

    // if previous is not an inline element
    if (!(prev instanceof Element && !isBlockEl(prev))) {
        // if there is no previous sib; or not a text node and should be indented. The previous sibling is
        // judged on its own layout, so the traversal root exemption does not apply: when serializing an
        // element's inner HTML that root is just the first of several siblings being printed, and treating
        // it specially would leave a leading newline on following text untrimmed, which would re-parse as
        // an extra space and make the output non-idempotent.
        if (prev == null || !(prev instanceof TextNode) && shouldIndent(prev, false))
            options |= Entities.TrimLeading;
    }

    if (next == null || !(next instanceof TextNode) && shouldIndent(next)) {
        options |= Entities.TrimTrailing;
    } else { // trim trailing whitespace if the next non-empty TextNode has leading whitespace
        next = nextNonBlank(next);
        if (next instanceof TextNode && StringUtil.isWhitespace(next.nodeValue().codePointAt(0)))
            options |= Entities.TrimTrailing;
    }

    return options;
}

final boolean shouldIndent(@Nullable Node node) {
    return shouldIndent(node, true);
}

