import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.Safelist;
import java.util.*;

public class RandValid {
    static Random rnd;
    static String[] blocks = {"div","p","h1","ul","li","table","tbody","tr","td","blockquote"};
    static String[] inlines = {"b","i","a","span","code","em","strong"};
    static String[] texts = {"a"," b ","a &amp; b","a < b","\"q\"","\\b","&lt;img src=x onerror=1&gt;","&nbsp;","\n","\t","  ","\n\t ","a&b","a&amp;amp;b","<</>>","&","&amp","日本語","𝄞","","script","<tag>","</tag>"};
    static String[] attrs = {"class='x'", "title='a &amp; b'", "onclick='alert(1)'", "href='javascript:alert(1)'", "href='http://x.com'", "style='x'", "id=1", "=''"};
    static String[] danger = {"<script>alert(1)</script>","<script>var x='<b>s</b>&amp;\"q\"\\u003c</script>","<style>a<b{}</style>","<img src=x onerror=1>","<font>","</font>","<center>","</center>","<!--<script>x</script>-->","<![CDATA[<b>]]>"};

    static String gen(boolean allowBlock, int depth) {
        StringBuilder sb = new StringBuilder();
        int n = rnd.nextInt(4);
        for (int i = 0; i < n; i++) {
            int kind = rnd.nextInt(10);
            if (kind < 4) sb.append(texts[rnd.nextInt(texts.length)]);
            else if (kind < 6) sb.append(danger[rnd.nextInt(danger.length)]);
            else if (kind == 6) {
                String t = inlines[rnd.nextInt(inlines.length)];
                sb.append("<").append(t);
                if (rnd.nextBoolean()) sb.append(" ").append(attrs[rnd.nextInt(attrs.length)]);
                sb.append(">").append(gen(false, depth+1)).append("</").append(t).append(">");
            } else if (kind == 7 && allowBlock && depth < 4) {
                String t = blocks[rnd.nextInt(blocks.length)];
                sb.append("<").append(t).append(">").append(gen(true, depth+1)).append("</").append(t).append(">");
            } else if (kind == 8) {
                sb.append("<pre>").append(texts[rnd.nextInt(texts.length)]).append("\n  x\t y</pre>");
            } else {
                sb.append("<br>");
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Safelist sl = Safelist.none().addTags("div","p","h1","ul","li","table","tbody","tr","td","blockquote","b","i","a","span","code","em","strong","pre","br","img");
        rnd = new Random(7);
        int fails = 0;
        for (int it = 0; it < 30000; it++) {
            String html = gen(true, 0);
            String c1, c2, c3;
            try { c1 = Jsoup.clean(html, sl); c2 = Jsoup.clean(c1, sl); c3 = Jsoup.clean(c2, sl); }
            catch (Exception e) { System.out.println("EX#"+it+": "+e); fails++; continue; }
            if (!c1.equals(c2) || !c2.equals(c3)) {
                System.out.println("NI#"+it+" IN: "+html.replace("\n","\\n").replace("\t","\\t"));
                System.out.println("   c1: "+c1.replace("\n","\\n").replace("\t","\\t"));
                System.out.println("   c2: "+c2.replace("\n","\\n").replace("\t","\\t"));
                if (++fails > 25) break;
            }
            Document d = Jsoup.parseBodyFragment(c1);
            for (Element e : d.getAllElements())
                for (Attribute at : e.attributes())
                    if (at.getKey().toLowerCase(Locale.ROOT).startsWith("on")) { System.out.println("LEAK#"+it+": "+html); }
        }
        System.out.println(fails==0 ? "ALL OK 30000 (valid content model)" : fails+" failures");
    }
}
