import org.jsoup.safety.Safelist;
import java.util.*;

public class Sem {
    static Random rnd = new Random(7);
    static String[] blocks = {"div","p","h1","ul","li","table","tbody","tr","td","blockquote","pre"};
    static String[] inlines = {"b","i","a","span","code","em","strong","br"};
    static String[] texts = {"a"," b ","word","a &amp; b","a < b","\"q\"","&nbsp;","\n","\t","  ","\n\t ","a&b","a&amp;amp;b","日本語","𝄞","","x","two words"};
    static String[] attrs = {"class='x'", "title='t'", "href='http://x.com'", "id=1","onclick='bad()'"};
    static String gen(boolean block, int d) {
        StringBuilder sb = new StringBuilder();
        for (int i=0,n=rnd.nextInt(4); i<n; i++) {
            int k = rnd.nextInt(8);
            if (k<3) sb.append(texts[rnd.nextInt(texts.length)]);
            else if (k==3) sb.append("<script>x<b>y</b>&amp;</script>");
            else if (k<6) { String t=inlines[rnd.nextInt(inlines.length)]; sb.append("<").append(t).append(">").append(gen(false,d+1)).append("</").append(t).append(">"); }
            else if (k==6 && block && d<3) { String t=blocks[rnd.nextInt(blocks.length)]; sb.append("<").append(t).append(">").append(gen(true,d+1)).append("</").append(t).append(">"); }
            else sb.append("<img src=x onerror=1>");
        }
        return sb.toString();
    }
    public static void main(String[] a) {
        Safelist sl = Safelist.none().addTags("div","p","h1","ul","li","table","tbody","tr","td","blockquote","pre","b","i","a","span","code","em","strong","br","img");
        int diff=0;
        for (int it=0; it<50000; it++) {
            String h = gen(true,0);
            // current build
            String c1 = Jsoup.clean(h, sl);
            String t1 = Jsoup.parseBodyFragment(c1).text();
            // expected safe text: parse raw, strip unsafe elements/attrs independently is complex;
            // instead compare text() between current clean and a "reference" computed by stripping tags loosely.
            // We check stability & no-loss: every non-whitespace char from safe text nodes must appear in order.
            String c2 = Jsoup.clean(c1, sl);
            if (!t1.equals(Jsoup.parseBodyFragment(c2).text())) { System.out.println("TEXT-UNSTABLE#"+it+": "+h); if(++diff>10) break; }
        }
        System.out.println(diff==0?"ALL TEXT STABLE 50000":diff+" text diffs");
    }
}
