import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;
import java.util.*;

public class Risk {
    public static void main(String[] args) {
        Safelist sl = Safelist.none().addTags("b","i","a","span","em","strong","div","p","br","pre","table","tbody","tr","td");
        String[] hs = {
            "<b>y </b>z",
            "<b>x<div></div>y </b>z",
            "<b>a<div>b</div>c </b>d",
            "<span>p<div></div>q </span>r s",
            "<i>word<br></i>next",
            "<em>x<div>y</div></em>z",
            "<b>a<br></b><b>b</b>",
            "<strong>m<div>n</div>o </strong> p",
            "<b>a </b><i>b</i>",
            "<span>x<div></div>y </span>z<i>w</i>",
            "<a>t<div></div>u </a>v w",
            "<b>1<div></div>2 </b>3 4",
            "<i>alpha<br></i>beta",
            "<b>a<div></div></b> b",
        };
        for (String h : hs) {
            String c = Jsoup.clean(h, sl);
            System.out.println(Jsoup.parseBodyFragment(c).text() + " || " + c.replace("\n", "\\n"));
        }
    }
}

