import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Safelist;
import org.jsoup.safety.Cleaner;

public class Cross {
    public static void main(String[] args) {
        String html = "<a onclick=1><div>x</div></a><b onclick=2><br>y</b><script>bad()</script>";
        Safelist s1 = Safelist.none().addTags("a", "div");
        Safelist s2 = Safelist.none().addTags("b", "br");

        String iso1 = Jsoup.clean(html, s1);
        String iso2 = Jsoup.clean(html, s2);
        // interleave many times
        String a = iso1, b = iso2;
        for (int i = 0; i < 50; i++) {
            a = Jsoup.clean(Jsoup.clean(a, s1), s2);
            b = Jsoup.clean(Jsoup.clean(b, s2), s1);
        }
        String reIso1 = Jsoup.clean(html, s1);
        String reIso2 = Jsoup.clean(html, s2);
        System.out.println("s1 isolated stable: " + iso1.equals(Jsoup.clean(iso1, s1)) + "  " + iso1.replace("\n","\\n"));
        System.out.println("s2 isolated stable: " + iso2.equals(Jsoup.clean(iso2, s2)) + "  " + iso2.replace("\n","\\n"));
        System.out.println("no safelist bleed (s1 result has no b/br, s2 no a/div): "
            + (!iso1.contains("<b") && !iso1.contains("<br") && !iso2.contains("<a") && !iso2.contains("<div")));

        // caller document immutability
        Document dirty = Jsoup.parseBodyFragment("<a onclick=1><div>x</div></a>");
        String before = dirty.body().html();
        new Cleaner(s1).clean(dirty);
        new Cleaner(s2).clean(dirty);
        System.out.println("caller doc unchanged: " + before.equals(dirty.body().html()));
    }
}

